package co.edu.cinematch.core.service;
import co.edu.cinematch.core.exception.*; import co.edu.cinematch.core.model.*; import co.edu.cinematch.core.repository.*; import java.util.*;
public class CineService { private final Repository<Cine> cines;private final Repository<Sala> salas;private final Repository<Asiento> asientos;public CineService(Repository<Cine> c,Repository<Sala>s,Repository<Asiento>a){cines=c;salas=s;asientos=a;}public Cine crearCine(Cine c){if(c==null||blank(c.getNombre()))throw new ValidationException("El nombre del cine es obligatorio.");if(blank(c.getCiudad()))throw new ValidationException("La ciudad es obligatoria.");return cines.save(c);}public List<Cine> listarCines(){return cines.findAll();}public Cine buscarCine(String id){return cines.findById(id).orElseThrow(()->new ResourceNotFoundException("Cine",id));}public Cine actualizarCine(String id,Cine d){if(d==null||blank(d.getNombre()))throw new ValidationException("El nombre del cine es obligatorio.");if(blank(d.getCiudad()))throw new ValidationException("La ciudad es obligatoria.");Cine c=buscarCine(id);c.setNombre(d.getNombre());c.setDireccion(d.getDireccion());c.setCiudad(d.getCiudad());return cines.save(c);}public void eliminarCine(String id){if(!cines.deleteById(id))throw new ResourceNotFoundException("Cine",id);}public Sala crearSala(String cineId,Sala s){buscarCine(cineId);if(s==null||blank(s.getNombre()))throw new ValidationException("El nombre de la sala es obligatorio.");if(s.getCapacidad()<=0)throw new ValidationException("La capacidad debe ser mayor a 0.");s.setCineId(cineId);Sala creada=salas.save(s);for(int i=1;i<=s.getCapacidad();i++){Asiento a=new Asiento(creada.getId(),String.valueOf((char)('A'+((i-1)/5))),((i-1)%5)+1);asientos.save(a);}return creada;}public List<Sala> listarSalas(String cineId){buscarCine(cineId);List<Sala> r=new ArrayList<>();for(Sala s:salas.findAll())if(cineId.equals(s.getCineId()))r.add(s);return r;}public Sala buscarSala(String id){return salas.findById(id).orElseThrow(()->new ResourceNotFoundException("Sala",id));}public Sala actualizarSala(String id,Sala d){if(d==null||blank(d.getNombre()))throw new ValidationException("El nombre de la sala es obligatorio.");if(d.getCapacidad()<=0)throw new ValidationException("La capacidad debe ser mayor a 0.");Sala s=buscarSala(id);s.setNombre(d.getNombre());s.setCapacidad(d.getCapacidad());s.setTipo(d.getTipo());return salas.save(s);}public void eliminarSala(String id){if(!salas.deleteById(id))throw new ResourceNotFoundException("Sala",id);}public List<Asiento> listarAsientos(String salaId){buscarSala(salaId);List<Asiento> r=new ArrayList<>();for(Asiento a:asientos.findAll())if(salaId.equals(a.getSalaId()))r.add(a);return r;}public Asiento buscarAsiento(String id){return asientos.findById(id).orElseThrow(()->new ResourceNotFoundException("Asiento",id));}private boolean blank(String v){return v==null||v.trim().isEmpty();} }
